<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="#" class="on">需审核信息列表</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="/admin.php?g=System&c=Classify&a=checkList" method="get">							<input type="hidden" value="Classify" name="c"></input>							<input type="hidden" value="checkList" name="a"></input>														<!--select name="city_id" style="width:200px;">								<option value="0">全部城市</option>								<if condition="!empty($city_list)">									<volist name="city_list" id="vo">										<option value="{pigcms{$vo['area_id']}"  <if condition="$vo['area_id'] eq $city_id">selected="selected"</if>>{pigcms{$vo['area_name']}</option>									</volist>								<else/>									<option value="">无</option>								</if>							</select-->							<if condition="$now_area['area_type'] lt 2 OR $system_session['level'] eq 2 ">								选择城市：								<div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}"  style="display:inline"></div>								<input type="submit" value="查询" class="button"/>								<button type="button" data-status='1' class="button more_check">批量审核</button>							</if>						</form>					</td>				</tr>			</table>			<if condition="$isverify eq 1">			<!--<table class="search_table" width="100%">				<tr>					<td>					</td>				</tr>			</table>-->			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>						</colgroup>						<thead>							<tr>								<th><input type="checkbox" id="all"></th>								<th>ID</th>								<th>一级分类</th>								<th>二级分类</th>								<th>标题</th>								<th>联系人姓名</th>								<th>联系人电话</th>								<th>最后更改时间</th>								<th>状态</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="!empty($needCheck)">								<volist name="needCheck" id="vo">									<tr>										<td><input type="checkbox" name="id_arr[]" value="{pigcms{$vo.id}"></td>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$ClassifyArr[$vo['fcid']]}</td>										<td>{pigcms{$ClassifyArr[$vo['cid']]}</td>										<td>{pigcms{$vo.title}</td>										<td>{pigcms{$vo.lxname}</td>										<td>{pigcms{$vo.lxtel}</td>																				<td>{pigcms{$vo.updatetime|date='Y-m-d H:i:s',###}</td>                    <if condition="empty($vo['status'])">                      <td class="red">未审核</td>                    </if>                    <if condition="$vo['status'] == 2">                      <td>已拒绝</td>                    </if>										<td class="textcenter">                      <if condition="empty($vo['status'])"><a href="javascript:void(0);" onclick="toCheck({pigcms{$vo.id});">审核</a>&nbsp; | &nbsp;</if>                      <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Classify/infodetail',array('vid'=>$vo['id']))}','查看信息详情',680,560,true,false,false,verifybtn,'edit',true);">查看详细</a>                      <if condition="empty($vo['status'])">&nbsp; | &nbsp;<a href="javascript:void(0);" onclick="toRejItem({pigcms{$vo.id});">拒绝</a></if>                    </td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="9">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="8">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>			<else/>			<table class="search_table" width="100%">				<tr>					<td>					您未开启发布信息需要审核功能，请到》系统设置》分类信息 中开启					</td>				</tr>			</table>			</if>		</div><script type="text/javascript">function toCheck(id){   if(confirm('您确定审核通过此项吗？')){    $.post("{pigcms{:U('Classify/toVerify')}",{vid:id},function(data){	  data=parseInt(data);	  if(!data){          window.location.reload();	   }     },'JSON');   }else{     return false;   }}/***拒绝***/function toRejItem(id){   layer.open({     type: 1,     area: '500px',     resize: false,     shadeClose: true,     title: '拒绝理由',     content: `          <div class="layui-form"  style="margin: 16px;">            <div class="demo-login-container">                <div class="layui-input-wrap">                  <textarea value="" id="reason" placeholder="请输入拒绝理由" style="width: 460px;height: 150px;" maxlength="255" autocomplete="off" class="layui-input" />                </div>            </div>          </div>        `,     btn: ['确定', '取消'],     btnAlign: 'c',     yes: function (index, layero, that) {       let refuse_reason = $('#reason').val();       if (refuse_reason === '') {         layer.msg('请输入拒绝理由')         return false       }       $.post("{pigcms{:U('Classify/rejItem')}", {vid: id, refuse_reason}, function (data) {         console.log(data)         if(data.code === 400){           layer.msg(data.info)           return false         }         layer.close(index);         layer.msg(data.info)         window.location.reload();       }, 'JSON');     },     cancel: function (index, layero, that) {       layer.close(index);     }   })}</script><script type="text/javascript">$(function(){	$('#all').click(function(){		var flag=this.checked;        $('input[type="checkbox"]').prop('checked', flag);    });    $('.more_check').click(function(){    	var ids_arr=[];    	$('input[type="checkbox"]:checked').not('#all').each(function(){    		ids_arr.push($(this).val());    	});    	if(ids_arr.length==0){    		layer.alert('至少选择一个待审核的信息',{ offset: (window.parent.parent.innerHeight / 4) + 'px'},function(index){		  		layer.close(index);		  				  	});		  	return false;    	}    	if(!confirm('您确定审核通过这些吗？')){    		return false;    	}    	    	$.post("{pigcms{:U('Classify/more_toVerify')}",{ids_arr:ids_arr},function(res){		  	layer.alert(res.info,{ offset: (window.parent.parent.innerHeight / 4) + 'px'},function(index){		  		layer.close(index);		  		if(res.status){		  			window.location.reload();		  		}		  				  	});	     },'JSON');		        });});</script><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js?{pigcms{:time()}"></script><include file="Public:footer"/>